    # Find the prominent horizontal bar; extend the vertical strokes below it
    # in the same color used to mark the missing portions.
    candidates = []
    for r, row in enumerate(grid):
        cols = [c for c, x in enumerate(row) if x == color]
        if len(cols) >= 5:
            candidates.append((len(cols), r))
    if not candidates:
        return out
    _, barrow = max(candidates)

    # Vertical strokes continuing below the bar, ending at a later horizontal bar.
    for c in range(w):
        if grid[barrow][c] != color:
            continue
        below = [r for r in range(barrow + 1, h) if grid[r][c] == color]
        if not below:
            continue
        end = max(below)
        for r in range(barrow + 1, end):
            if grid[r][c] == bg:
                out[r][c] = 4
    return out
